import { createHash } from 'node:crypto';
import sharp from 'sharp';
import { strictHttpsUrl } from '../adminPinnedHttps';
import { maxCoverArtInputBytes, maxCoverArtInputPixels, validateCoverArtFile } from '../../services/image/imageStorageService';
import { scheduleCoverArtVariant, type CoverArtVariantScheduler } from '../../services/image/coverArtVariantScheduler';
import { METADATA_LOOKUP_HOSTS, METADATA_LOOKUP_LIMITS, MetadataLookupInputError, MetadataLookupSourceError, type CoverArtListing } from './lookupContract';
import { normalizeCoverArtImageId, normalizeMusicBrainzId } from './lookupIdentifiers';
import { LookupShapeError, array, boolean, integer, object, oneOf, string, validateLookupShape } from './lookupResponseShape';
import { requestLookupBytes, requestLookupJson, type LookupCallOptions, type LookupClientDependencies } from './lookupSourceRequest';

/**
 * Cover Art Archive client: a release's image listing, and its front artwork. Both redirect through
 * archive.org to a storage node, so each hop is allowlisted by host and bound to the requested
 * release's MBID. The listing returns only image identities, flags, types and available sizes,
 * never a URL; front artwork is fetched from a server-built URL, never one a response named, and
 * is validated and completely decoded before anyone sees it.
 */
const requireMbid = (value: unknown) => {
    const id = normalizeMusicBrainzId(value);
    if (!id) throw new MetadataLookupInputError('identifier');
    return id;
};

export const coverArtListingUrl = (releaseId: string) => new URL(`https://${METADATA_LOOKUP_HOSTS.coverArtArchive}/release/${requireMbid(releaseId)}`);

/** Hop 0 is the archive listing; later hops may only reach archive.org or a storage node for the same MBID. */
export const coverArtDestination = (releaseId: string) => {
    const id = requireMbid(releaseId);
    const storagePath = new RegExp(`^/\\d+/items/mbid-${id}/index\\.json$`);
    return (url: URL, hop: number): URL | null => {
        const strict = strictHttpsUrl(url.href);
        if (!strict || strict.search) return null;
        const { hostname, pathname } = strict;
        if (hostname === METADATA_LOOKUP_HOSTS.coverArtArchive && (pathname === `/release/${id}` || pathname === `/release/${id}/`)) return strict;
        if (hop === 0) return null;
        if (hostname === METADATA_LOOKUP_HOSTS.archive && pathname === `/download/mbid-${id}/index.json`) return strict;
        if (METADATA_LOOKUP_HOSTS.archiveStorage.test(hostname) && storagePath.test(pathname)) return strict;
        return null;
    };
};

const knownTypes = new Set(['Front', 'Back', 'Booklet', 'Medium', 'Obi', 'Spine', 'Track', 'Tray', 'Sticker', 'Poster', 'Liner',
    'Watermark', 'Raw/Unedited', 'Matrix/Runout', 'Top', 'Bottom', 'Panel', 'Other']);
const thumbnail = string(2048, { optional: true });
/** Allowlisted listing shape; the recorder trims fixtures with it. */
export const coverArtShape = object({
    images: array(object({
        id: oneOf(integer(1, Number.MAX_SAFE_INTEGER), string(20, { pattern: /^\d{1,20}$/ })),
        front: boolean(), back: boolean(), approved: boolean(),
        types: array(string(64), 30),
        thumbnails: object({ 250: thumbnail, 500: thumbnail, 1200: thumbnail }, { optional: true })
    }), 200),
    release: string(2048)
});

type RawImage = { id: number | string; front: boolean; back: boolean; approved: boolean; types: string[]; thumbnails?: Record<string, string> };

/** The listing must name the requested release; unknown image types are dropped. */
export const parseCoverArtListing = (json: unknown, releaseId: string): CoverArtListing => {
    const id = requireMbid(releaseId);
    const raw = validateLookupShape<{ images: RawImage[]; release: string }>(coverArtShape, json);
    if (raw.release !== `https://musicbrainz.org/release/${id}` && raw.release !== `http://musicbrainz.org/release/${id}`) throw new LookupShapeError();
    return {
        releaseId: id,
        images: raw.images.map(image => {
            const imageId = normalizeCoverArtImageId(image.id);
            if (!imageId) throw new LookupShapeError();
            const sizes = ([250, 500, 1200] as const).filter(size => image.thumbnails?.[size] !== undefined);
            return { imageId, front: image.front, back: image.back, approved: image.approved, types: image.types.filter(type => knownTypes.has(type)), sizes };
        })
    };
};

/** The two front thumbnails lookup uses: 1200 px for a staged cover, 500 px for a candidate preview. */
export type CoverArtFrontSize = 500 | 1200;
/** The release's front thumbnail, built by the server from the candidate's MBID. */
export const coverArtFrontUrl = (releaseId: string, size: CoverArtFrontSize) =>
    new URL(`https://${METADATA_LOOKUP_HOSTS.coverArtArchive}/release/${requireMbid(releaseId)}/front-${size}`);
/**
 * Hop 0 is exactly the front URL; later hops may only reach the same release's thumbnail of that size: a Cover Art Archive image
 * URL, the archive.org download or a storage node's item path. No hop may carry a query.
 */
export const coverArtFrontDestination = (releaseId: string, size: CoverArtFrontSize) => {
    const id = requireMbid(releaseId), front = coverArtFrontUrl(id, size).href;
    const imagePath = new RegExp(`^/release/${id}/\\d{1,20}-${size}\\.jpg$`);
    const archivePath = new RegExp(`^/download/mbid-${id}/mbid-${id}-\\d{1,20}_thumb${size}\\.jpg$`);
    const storagePath = new RegExp(`^/\\d{1,6}/items/mbid-${id}/mbid-${id}-\\d{1,20}_thumb${size}\\.jpg$`);
    return (url: URL, hop: number): URL | null => {
        const strict = strictHttpsUrl(url.href);
        if (!strict || strict.search || strict.href.includes('?')) return null;
        if (hop === 0) return strict.href === front ? strict : null;
        const { hostname, pathname } = strict;
        if (hostname === METADATA_LOOKUP_HOSTS.coverArtArchive && imagePath.test(pathname)) return strict;
        if (hostname === METADATA_LOOKUP_HOSTS.archive && archivePath.test(pathname)) return strict;
        if (METADATA_LOOKUP_HOSTS.archiveStorage.test(hostname) && storagePath.test(pathname)) return strict;
        return null;
    };
};

const artworkTypes = ['image/jpeg', 'image/png', 'image/webp'] as const;
/** Validated, completely decoded front artwork: its unchanged bytes, allowlisted type and SHA-256. */
export type LookupArtwork = { bytes: Buffer; contentType: typeof artworkTypes[number]; sha256: string };
export type CoverArtFrontOptions = LookupCallOptions & { clientKey?: string };
/** Native image work shares the cover scheduler; its own failures (a full queue) are unavailable, an abort cancelled. */
const scheduled = async <T>(schedule: CoverArtVariantScheduler, clientKey: string | undefined, signal: AbortSignal, work: () => Promise<T>): Promise<T> => {
    try { return await schedule(clientKey ?? 'metadata-lookup', signal, async () => { signal.throwIfAborted(); return work(); }); }
    catch (error) {
        if (error instanceof MetadataLookupSourceError) throw error;
        throw new MetadataLookupSourceError('coverartarchive', signal.aborted ? 'cancelled' : 'unavailable');
    }
};

export interface CoverArtClient {
    /** Null when the release has no Cover Art Archive listing (404). */
    listRelease(releaseId: string, options: LookupCallOptions): Promise<CoverArtListing | null>;
    /**
     * The release's front thumbnail of `size`, validated (byte bound, signature matching its type, at most 16 MP, neither side
     * above `size` pixels) and completely decoded in the shared cover scheduler, or null when Cover Art Archive has none (404).
     * Anything else that is not such an image is `invalidResponse`; the bytes are never cached.
     */
    front(releaseId: string, size: CoverArtFrontSize, options: CoverArtFrontOptions): Promise<LookupArtwork | null>;
}

/** `schedule` defaults to the process-wide cover scheduler (tests inject their own). */
export const createCoverArtClient = (dependencies: LookupClientDependencies & { schedule?: CoverArtVariantScheduler }): CoverArtClient => ({
    async listRelease(releaseId, options) {
        const url = coverArtListingUrl(releaseId);
        return requestLookupJson<CoverArtListing | null>({
            source: 'coverartarchive', url, destination: coverArtDestination(releaseId), accept: 'application/json',
            contentTypes: ['application/json'], maximumBytes: METADATA_LOOKUP_LIMITS.coverArtBytes,
            deadlineMs: METADATA_LOOKUP_LIMITS.requestDeadlineMs.coverartarchive, rateLimitStatuses: [429, 503],
            emptyStatuses: [404], emptyValue: null, parse: json => parseCoverArtListing(json, releaseId)
        }, options, dependencies);
    },
    async front(releaseId, size, options) {
        const id = requireMbid(releaseId);
        if (size !== 500 && size !== 1200) throw new MetadataLookupInputError('identifier');
        const answer = await requestLookupBytes({
            source: 'coverartarchive', url: coverArtFrontUrl(id, size), destination: coverArtFrontDestination(id, size), accept: artworkTypes.join(', '),
            contentTypes: artworkTypes, maximumBytes: Math.min(METADATA_LOOKUP_LIMITS.artworkBytes, maxCoverArtInputBytes),
            deadlineMs: METADATA_LOOKUP_LIMITS.requestDeadlineMs.coverartarchive, rateLimitStatuses: [429, 503], emptyStatuses: [404]
        }, options, dependencies);
        if (!answer) return null;
        const contentType = answer.contentType as LookupArtwork['contentType'], bytes = answer.body;
        await scheduled(dependencies.schedule ?? scheduleCoverArtVariant, options.clientKey, options.signal, async () => {
            try {
                await validateCoverArtFile({ buffer: bytes, size: bytes.length, mimetype: contentType, originalname: `front-${size}` } as Express.Multer.File);
                // A thumbnail of `size` is never larger than that; the staged cover keeps these bytes unchanged.
                const { width = 0, height = 0 } = await sharp(bytes, { failOn: 'error', limitInputPixels: maxCoverArtInputPixels }).metadata();
                if (!width || !height || Math.max(width, height) > size) throw new Error('Larger than its thumbnail size');
            } catch { throw new MetadataLookupSourceError('coverartarchive', 'invalidResponse'); }
        });
        return { bytes, contentType, sha256: createHash('sha256').update(bytes).digest('hex') };
    }
});

/**
 * A transient candidate preview: the validated artwork converted to WebP within 500 px, in the shared cover scheduler. Nothing is
 * stored; a decoding failure is `invalidResponse`.
 */
export const lookupArtworkWebp = (artwork: LookupArtwork, signal: AbortSignal, clientKey: string, schedule: CoverArtVariantScheduler = scheduleCoverArtVariant): Promise<Buffer> =>
    scheduled(schedule, clientKey, signal, async () => {
        const image = sharp(artwork.bytes, { failOn: 'error', limitInputPixels: maxCoverArtInputPixels }).timeout({ seconds: 10 });
        const abort = () => image.destroy();
        signal.addEventListener('abort', abort, { once: true });
        try {
            const output = await image.rotate().resize(500, 500, { fit: 'inside', withoutEnlargement: true }).webp({ quality: 80 }).toBuffer();
            signal.throwIfAborted();
            return output;
        } catch (error) {
            if (signal.aborted) throw error;
            throw new MetadataLookupSourceError('coverartarchive', 'invalidResponse');
        } finally { signal.removeEventListener('abort', abort); image.destroy(); }
    });
